mapper.select:
SELECT GRP_CD AS grpCd, CD_VAL AS cdVal, CD_NM AS cdNm, SORT_NO AS sortNo
  FROM CD_COMMON
 WHERE GRP_CD = #{grpCd}
   AND CD_VAL = #{cdVal}

mapper.update:
UPDATE CD_COMMON
   SET CD_NM      = #{cdNm},
       SORT_NO    = #{sortNo},
       USE_YN     = #{useYn},
       ATTR1      = #{attr1,jdbcType=VARCHAR},
       UPDATED_AT = SYSTIMESTAMP,
       UPDATED_BY = #{updatedBy}
 WHERE GRP_CD = #{grpCd}
   AND CD_VAL = #{cdVal}

mapper.select:
SELECT USE_YN
  FROM CD_COMMON
 WHERE GRP_CD = #{grpCd}
   AND CD_VAL = #{cdVal}

mapper.update:
UPDATE CD_COMMON
   SET USE_YN     = 'N',
       UPDATED_AT = SYSTIMESTAMP,
